BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "ideal_functions" (
	"id"	INTEGER NOT NULL,
	"x"	FLOAT,
	"y1"	FLOAT,
	"y2"	FLOAT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "test_results" (
	"id"	INTEGER NOT NULL,
	"x"	FLOAT,
	"y"	FLOAT,
	"delta_y"	FLOAT,
	"ideal_function_id"	INTEGER,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "training_data" (
	"id"	INTEGER NOT NULL,
	"x"	FLOAT,
	"y1"	FLOAT,
	"y2"	FLOAT,
	"y3"	FLOAT,
	"y4"	FLOAT,
	PRIMARY KEY("id")
);
